"use strict";(globalThis.webpackChunkjc_community_site=globalThis.webpackChunkjc_community_site||[]).push([[17920],{93086(e,t,o){o.r(t),o.d(t,{assets:()=>c,contentTitle:()=>i,default:()=>p,frontMatter:()=>a,metadata:()=>r,toc:()=>u});const r=JSON.parse('{"id":"general/jumpcloud-reports-various-improvements","title":"Jumpcloud Reports Various Improvements","description":"By dwjohn","source":"@site/docs/general/jumpcloud-reports-various-improvements.md","sourceDirName":"general","slug":"/general/jumpcloud-reports-various-improvements","permalink":"/jc-community-archive/general/jumpcloud-reports-various-improvements","draft":false,"unlisted":false,"tags":[],"version":"current","frontMatter":{"title":"Jumpcloud Reports Various Improvements","description":"By dwjohn"},"sidebar":"docs","previous":{"title":"Jumpcloud Reports Api Endpoints Live","permalink":"/jc-community-archive/general/jumpcloud-reports-api-endpoints-live"},"next":{"title":"Jumpcloud S Perspective On July S Global It Outage","permalink":"/jc-community-archive/general/jumpcloud-s-perspective-on-july-s-global-it-outage"}}');var s=o(74848),n=o(28453);const a={title:"Jumpcloud Reports Various Improvements",description:"By dwjohn"},i=void 0,c={},u=[];function l(e){const t={a:"a",em:"em",p:"p",strong:"strong",...(0,n.R)(),...e.components};return(0,s.jsxs)(s.Fragment,{children:[(0,s.jsx)(t.p,{children:"Hey JumpCloud Community. Today, I am here to share several improvements to our JumpCloud Reports offering. Some of them are small but I believe they will be valuable in helping to complete tasks and improve efficiency. In any Product Led Growth organization, feedback from customers is critical to the overall product direction. All of the improvements discussed today resulted from feature requests or feedback from customers."}),"\n",(0,s.jsx)(t.p,{children:(0,s.jsx)(t.strong,{children:"Admin/Sudo Access in Users to Devices Report"})}),"\n",(0,s.jsx)(t.p,{children:"The Users to Devices Report has always been the most popular JumpCloud Report in terms of usage. Having an artifact that shows all users and their bound devices is huge for compliance, auditing, troubleshooting, etc. Several customers have reached out to request that we add whether or not the user that is bound to a device has admin/sudo privileges to that device. The Users to Devices Report now contains this field."}),"\n",(0,s.jsx)(t.p,{children:(0,s.jsx)(t.em,{children:"Users to Devices Report Example"})}),"\n",(0,s.jsx)(t.p,{children:(0,s.jsx)(t.strong,{children:"User State Data in Users to Resources Reports"})}),"\n",(0,s.jsx)(t.p,{children:"During the development process for the newly released Users to User Groups Report, we discussed the importance of user_state data in that report. The field provides the current status or state for that user on the JumpCloud platform. Values for this field include activated, suspended, and staged. During those discussions, we felt that it would also be valuable data to include in the various User to Resources Reports for many of the same reasons that we included it in the Users to User Groups Report.\xa0 This group of reports include Users to Devices, Users to Directories, Users to SSO, Users to LDAP, and Users to RADIUS. Whether leveraging these reports for compliance, auditing, troubleshooting or automation, also having the current user_state can be valuable."}),"\n",(0,s.jsx)(t.p,{children:(0,s.jsx)(t.em,{children:"Users to SSO Report Example"})}),"\n",(0,s.jsx)(t.p,{children:(0,s.jsx)(t.strong,{children:"Alternate JumpCloud Reports Discovery Points"})}),"\n",(0,s.jsxs)(t.p,{children:["Back in October, I posted about a new way to find and run the ",(0,s.jsx)(t.a,{href:"https://community.jumpcloud.com/t5/jumpcloud-product-news/new-discovery-os-patch-management-policy-report/td-p/1576",children:"OS Patch Management Policy Report"}),". The addition here was that when the Admin is on the OS Patch Management Policy tab, they are presented with a button that enables them to run the OS Patch Management Policy Report directly from that location.\xa0"]}),"\n",(0,s.jsx)(t.p,{children:"As a result of this change, we saw a significant increase in our usage data for that report. We have taken the same approach with the reports that have been released since the OS Patch Policy Report (Browser Patch Policy Report and Users to User Groups Report). We are also going back to the previous reports and providing an alternate discovery point for their relevant management pages. This includes all of the User to Resources Reports (Devices, Directories, SSO, LDAP, and RADIUS. All of these alternate discovery points should make it easier for Admins to find the report and run them while in the context of managing those areas."}),"\n",(0,s.jsx)(t.p,{children:(0,s.jsx)(t.em,{children:"Users to Devices Report on the Devices Page"})}),"\n",(0,s.jsx)(t.p,{children:(0,s.jsx)(t.strong,{children:"Wrap Up"})}),"\n",(0,s.jsx)(t.p,{children:"These changes represent the best of what JumpCloud customers and community bring to the conversation around \u201cmaking work happen\u201d. Very often, the best ideas for new features or improvements come from our customers and community. Keep em coming."})]})}function p(e={}){const{wrapper:t}={...(0,n.R)(),...e.components};return t?(0,s.jsx)(t,{...e,children:(0,s.jsx)(l,{...e})}):l(e)}},28453(e,t,o){o.d(t,{R:()=>a,x:()=>i});var r=o(96540);const s={},n=r.createContext(s);function a(e){const t=r.useContext(n);return r.useMemo(function(){return"function"==typeof e?e(t):{...t,...e}},[t,e])}function i(e){let t;return t=e.disableParentContext?"function"==typeof e.components?e.components(s):e.components||s:a(e.components),r.createElement(n.Provider,{value:t},e.children)}}}]);